  if(a==='scope'||a==='display'){view()[a==='scope'?'scope':'display']=el.dataset.value;if(a==='scope')person='';viewDirty=true;selected.clear();menu=null;redraw();await saveView();return;}
  if(a==='people'){openMenu('people',el);return;}
  if(a==='copy-link'){try{await navigator.clipboard.writeText(window.location.origin+window.location.pathname+'#tasks');ctx.toast?.(tr('链接已复制；访问仍需原有授权','Link copied; existing authorization is required'));}catch{error=tr('无法复制，请复制地址栏链接','Copy the link from your address bar');redraw();}return;}
  if(a==='calendar-prev'||a==='calendar-next'||a==='calendar-today'){monthOffset=a==='calendar-today'?0:monthOffset+(a==='calendar-next'?1:-1);redraw();return;}
  if(a==='calendar-weekends'){view().showWeekends=!view().showWeekends;viewDirty=true;redraw();await saveView();return;}
  if(a==='updates'){await loadUpdates(t);return;}
  if(a==='close-updates'){closeUpdates();return;}
  if(a==='update-edit'){thread.editing=el.dataset.uid;thread.editDraft=null;thread.confirmDelete=null;redraw();const ta=document.querySelector('[data-mb-edit-draft]');if(ta){ta.focus();ta.setSelectionRange(ta.value.length,ta.value.length);}return;}
  if(a==='update-edit-cancel'){thread.editing=null;thread.editDraft=null;redraw();return;}
  if(a==='update-delete'){thread.confirmDelete=el.dataset.uid;thread.editing=null;redraw();return;}
  if(a==='update-delete-no'){thread.confirmDelete=null;redraw();return;}
  if(a==='update-edit-save'||a==='update-delete-yes'){const active=thread,who=identity,uid=el.dataset.uid,item=active.items.find(x=>x.id===uid);if(!item)return;const body=(active.editDraft??item.body).trim();if(a==='update-edit-save'&&!body){active.error=tr('更新内容不能为空；如果不需要这条更新，请删除它。','An update cannot be empty; delete it instead.');redraw();return;}pending=true;active.error='';redraw();
   try{if(a==='update-edit-save'){const r=await ctx.api.post('/tasks/'+encodeURIComponent(active.id)+'/updates/'+encodeURIComponent(uid)+'/edit',{body});Object.assign(item,{body:r.body,edited_at:r.edited_at});active.editing=null;active.editDraft=null;ctx.toast?.(tr('更新已修改','Update edited'));}
   else{await ctx.api.delete('/tasks/'+encodeURIComponent(active.id)+'/updates/'+encodeURIComponent(uid));active.items=active.items.filter(x=>x.id!==uid);active.confirmDelete=null;ctx.toast?.(tr('更新已删除','Update deleted'));if(identity===who)await refresh();}}
   catch(err){if(identity===who&&thread===active)active.error=err.message;}finally{pending=false;redraw();}return;}
  if(a==='retry-score'){const active=thread,who=identity,c=active?.completion?.completion;if(!c)return;pending=true;active.error='';redraw();try{const saved=await ctx.api.post('/tasks/'+encodeURIComponent(active.id)+'/completion/rescore',{completionId:c.id});if(identity===who&&thread===active){ctx.toast?.(completionNotice(saved?.completion));await refresh();await loadUpdates(data.items.find(t=>t.id===active.id),active.draft);}}catch(e){if(thread===active)active.error=e.message;}finally{pending=false;redraw();}return;}
  if(a==='updates-reload'){const id=thread.id,draft=thread.draft;await refresh();await loadUpdates(data.items.find(t=>t.id===id),draft);return;}
  if(a==='dashboard-status'){status=el.dataset.value;redraw();return;}
