  if(a==='clear-filters'){query='';person='';status='';redraw();return;}
  if(a==='close-menu'){menu=null;redraw();return;}if(a==='expand-all'){const ids=parentsWithKids();if(el.dataset.value==='collapse')ids.forEach(id=>expanded.delete(id));else ids.forEach(id=>expanded.add(id));redraw();return;}if(a==='expand'){expanded.has(t.id)?expanded.delete(t.id):expanded.add(t.id);redraw();return;}if(a==='collapse-group'){const k=el.dataset.key;view().collapsed=view().collapsed.includes(k)?view().collapsed.filter(x=>x!==k):[...view().collapsed,k];redraw();await saveView();return;}
  if(['person','filter','sort','hide','groupBy','settings','add-group','batch-status','batch-group','task-menu'].includes(a)){if(['settings','add-group'].includes(a)&&ctx.actor.role!=='manager'){ctx.toast?.(tr('分组与标签由负责人设置','A manager edits shared groups and labels'));return;}openMenu(a,el,{id:el.dataset.id});return;}
  if((a==='edit-cell'&&['owner','due','priority'].includes(el.dataset.field)||a==='rename')&&lockedFor(t)){menu=null;ctx.toast?.(lockMsg(t));redraw();return;}if(a==='edit-cell'){if(el.dataset.field==='owner'&&ctx.actor.role!=='manager'){ctx.toast?.(tr('由负责人调整任务分派','Ask a manager to reassign tasks'));return;}openMenu('cell',el,{id:t.id,field:el.dataset.field});return;}
