 document.addEventListener('keydown',e=>{const h=e.target.closest?.('[data-mb-resize]');if(h?.closest('[data-task-board-root]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();applyWidth(h.dataset.mbResize,widthFor(h.dataset.mbResize)+(e.key==='ArrowRight'?16:-16));void saveView().catch(err=>{error=err.message;redraw();});}});
 let rowDragged=null;
